let cachedData: AppStoreData | null = null;

export function loadStore(): AppStoreData {
  if (cachedData) return cachedData;

  let raw: string | null = null;
  try {
    raw = localStorage.getItem(STORAGE_KEY);
  } catch (e) {
    console.error('Storage access error', e);
  }

  if (raw) {
    try {
      const parsed = JSON.parse(raw);
      // Migration from older v1 HTML file format or partial format
      const migrated: AppStoreData = {
        version: '2.0',
        products: Array.isArray(parsed.products) && parsed.products.length > 0 ? parsed.products : SEED_PRODUCTS,
        invoices: Array.isArray(parsed.invoices) ? parsed.invoices : SEED_INVOICES,
        heldBills: Array.isArray(parsed.heldBills) ? parsed.heldBills : [],
        customers: Array.isArray(parsed.customers) && parsed.customers.length > 0 ? parsed.customers : SEED_CUSTOMERS,
        customerPayments: Array.isArray(parsed.customerPayments) ? parsed.customerPayments : [],
        suppliers: Array.isArray(parsed.suppliers) && parsed.suppliers.length > 0 ? parsed.suppliers : SEED_SUPPLIERS,
        purchases: Array.isArray(parsed.purchases) ? parsed.purchases : [],
        expenses: Array.isArray(parsed.expenses) && parsed.expenses.length > 0 ? parsed.expenses : SEED_EXPENSES,
        stockAdjustments: Array.isArray(parsed.stockAdjustments) ? parsed.stockAdjustments : [],
        shopInfo: {
          ...DEFAULT_SHOP_INFO,
          ...(parsed.shopInfo || {}),
          gst: (parsed.shopInfo && parsed.shopInfo.gst) || parsed.shopGst || DEFAULT_SHOP_INFO.gst,
          logo: (parsed.shopInfo && parsed.shopInfo.logo) || SHOP_LOGO_DATA_URI,
          nextInvoiceNo: parsed.nextInvoiceNo || DEFAULT_SHOP_INFO.nextInvoiceNo,
        },
      };

      // Ensure every product has purchasePrice, minStockThreshold, taxRate
      migrated.products = migrated.products.map((p, idx) => {
        const legacyPrice = (p as unknown as { price?: number }).price || 0;
        return {
          ...p,
          id: p.id || `p${idx + 1}`,
          purchasePrice: p.purchasePrice !== undefined ? p.purchasePrice : Math.round(legacyPrice * 0.75),
          sellingPrice: p.sellingPrice || legacyPrice || 0,
          minStockThreshold: p.minStockThreshold || 5,
          taxRate: p.taxRate !== undefined ? p.taxRate : 18,
          hsnCode: p.hsnCode || '8205',
        };
      });

      // Normalize legacy invoices (e.g. HW-0001, HW-0002, HW-0003 from v1 HTML app)
      migrated.invoices = migrated.invoices.map((inv, idx) => {
        const rawInv = inv as unknown as Record<string, unknown>;
        const subtotal = Number(rawInv.subtotal) || 0;
        const discountPct = Number(rawInv.discountPct) || 0;
        const discountAmt = Number(rawInv.discountAmt) || 0;
        const taxAmt = Number(rawInv.taxAmt) || 0;
        const rawTotal = Number(rawInv.total) || 0;
        const rawTaxable = Number(rawInv.taxableAmount) || 0;
        const taxableAmount =
          rawTaxable > 0
            ? rawTaxable
            : subtotal - discountAmt > 0
            ? Number((subtotal - discountAmt).toFixed(2))
            : Math.max(0, Number((rawTotal - taxAmt).toFixed(2)));
        const total = rawTotal > 0 ? rawTotal : Number((taxableAmount + taxAmt).toFixed(2));
        const taxType = (rawInv.taxType as 'intra_state' | 'inter_state') || 'intra_state';
        const cgstAmount =
          rawInv.cgstAmount !== undefined
            ? Number(rawInv.cgstAmount)
            : taxType === 'intra_state'
            ? Number((taxAmt / 2).toFixed(2))
            : 0;
        const sgstAmount =
          rawInv.sgstAmount !== undefined
            ? Number(rawInv.sgstAmount)
            : taxType === 'intra_state'
            ? Number((taxAmt / 2).toFixed(2))
            : 0;
        const igstAmount =
          rawInv.igstAmount !== undefined
            ? Number(rawInv.igstAmount)
            : taxType === 'inter_state'
            ? Number(taxAmt.toFixed(2))
            : 0;

        const rawItems = Array.isArray(rawInv.items) ? rawInv.items : [];
        const normalizedItems = rawItems.map((itemObj: Record<string, unknown>, iIdx: number) => {
          const qty = Number(itemObj.qty) || 1;
          const price = Number(itemObj.price ?? itemObj.sellingPrice) || 0;
          const itemDiscPct = Number(itemObj.itemDiscountPct) || 0;
          const itemDiscAmt = Number(itemObj.itemDiscountAmt) || Number(((qty * price * itemDiscPct) / 100).toFixed(2));
          const lineGross = Math.max(0, qty * price - itemDiscAmt);
          // Proportionally apply bill discount if item taxableAmount is missing
          const billDiscShare = subtotal > 0 ? (lineGross / subtotal) * discountAmt : 0;
          const itemTaxable =
            itemObj.taxableAmount !== undefined && Number(itemObj.taxableAmount) > 0
              ? Number(itemObj.taxableAmount)
              : Number(Math.max(0, lineGross - billDiscShare).toFixed(2));
          const taxRate =
            itemObj.taxRate !== undefined
              ? Number(itemObj.taxRate)
              : taxableAmount > 0 && taxAmt === 0
              ? 0
              : 18;
          const itemTaxTotal = Number(((itemTaxable * taxRate) / 100).toFixed(2));
          const itemCgst =
            itemObj.cgstAmount !== undefined
              ? Number(itemObj.cgstAmount)
              : taxType === 'intra_state'
              ? Number((itemTaxTotal / 2).toFixed(2))
              : 0;
          const itemSgst =
            itemObj.sgstAmount !== undefined
              ? Number(itemObj.sgstAmount)
              : taxType === 'intra_state'
              ? Number((itemTaxTotal / 2).toFixed(2))
              : 0;
          const itemIgst =
            itemObj.igstAmount !== undefined
              ? Number(itemObj.igstAmount)
              : taxType === 'inter_state'
              ? itemTaxTotal
              : 0;
          const itemTotal =
            itemObj.total !== undefined && Number(itemObj.total) > 0
              ? Number(itemObj.total)
              : Number((itemTaxable + itemCgst + itemSgst + itemIgst).toFixed(2));

          return {
            productId: String(itemObj.productId || itemObj.id || `p_${iIdx}`),
            name: String(itemObj.name || 'Hardware Item'),
            sku: String(itemObj.sku || `SKU-${iIdx + 1}`),
            hsnCode: String(itemObj.hsnCode || '4412'),
            qty,
            unit: (itemObj.unit as Invoice['items'][number]['unit']) || 'Pcs',
            price,
            purchasePrice: Number(itemObj.purchasePrice) || Math.round(price * 0.75),
            itemDiscountPct: itemDiscPct,
            itemDiscountAmt: itemDiscAmt,
            taxableAmount: itemTaxable,
            taxRate,
            cgstAmount: itemCgst,
            sgstAmount: itemSgst,
            igstAmount: itemIgst,
            total: itemTotal,
          };
        });

        const amountPaid =
          rawInv.amountPaid !== undefined ? Number(rawInv.amountPaid) : total;
        const balanceDue =
          rawInv.balanceDue !== undefined
            ? Number(rawInv.balanceDue)
            : Math.max(0, Number((total - amountPaid).toFixed(2)));

        return {
          ...inv,
          id: String(rawInv.id || `inv_${idx + 1}`),
          number: String(rawInv.number || `HW-000${idx + 1}`),
          date: String(rawInv.date || new Date().toISOString()),
          customerName: String(rawInv.customerName || rawInv.customer || 'Walk-in Customer'),
          customerPhone: String(rawInv.customerPhone || rawInv.phone || ''),
          customerGst: String(rawInv.customerGst || rawInv.gst || ''),
          customerAddress: String(rawInv.customerAddress || ''),
          items: normalizedItems,
          subtotal,
          discountPct,
          discountAmt,
          taxableAmount,
          taxType,
          cgstAmount,
          sgstAmount,
          igstAmount,
          taxAmt,
          roundOff: Number(rawInv.roundOff) || 0,
          total,
          paymentMethod: (rawInv.paymentMethod as Invoice['paymentMethod']) || 'cash',
          paymentStatus:
            (rawInv.paymentStatus as Invoice['paymentStatus']) ||
            (balanceDue > 0 ? 'partial' : 'paid'),
          amountPaid,
          balanceDue,
        };
      });

      cachedData = migrated;
      saveStore(migrated);
      return migrated;
    } catch (e) {
      console.warn('Damaged storage, restoring seed data', e);
    }
  }

  // Initial fresh setup
  const initial: AppStoreData = {
    version: '2.0',
    products: SEED_PRODUCTS,
    invoices: SEED_INVOICES,
    heldBills: [],
    customers: SEED_CUSTOMERS,
    customerPayments: [],
    suppliers: SEED_SUPPLIERS,
    purchases: [],
    expenses: SEED_EXPENSES,
    stockAdjustments: [],
    shopInfo: DEFAULT_SHOP_INFO,
  };

  cachedData = initial;
  saveStore(initial);
  createSnapshot('Initial seed setup', 'manual', initial);
  return initial;
}

export function saveStore(data: AppStoreData): boolean {
  try {
    cachedData = data;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    if (typeof window !== 'undefined' && window.location.protocol !== 'file:') {
      fetch('/api/store', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      }).catch(() => {
        // Offline or standalone mode: localStorage already has the latest state
      });
    }
    return true;
  } catch (e) {
    console.error('Failed to save store to localStorage', e);
    return false;
  }
}

/* ---------------- Snapshot / Automatic Backups ---------------- */

export function readSnapshots(): BackupSnapshot[] {
  try {
    const raw = localStorage.getItem(BACKUP_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch (e) {
    return [];
  }
}

export function writeSnapshots(list: BackupSnapshot[]): boolean {
  while (true) {
    try {
      localStorage.setItem(BACKUP_KEY, JSON.stringify(list));
      return true;
    } catch (e) {
      if (list.length <= 1) return false;
      list.shift(); // Drop oldest to recover quota
    }
  }
}

export function createSnapshot(
  label: string,
  kind: 'daily' | 'bill' | 'manual' | 'pre-restore',
  customData?: AppStoreData
): BackupSnapshot | null {
  try {
    const dataObj = customData || loadStore();
    const list = readSnapshots();
    const snap: BackupSnapshot = {
      id: 'snap_' + Date.now() + '_' + Math.floor(Math.random() * 1000),
      ts: new Date().toISOString(),
      kind,
      label,
      products: dataObj.products.length,
      invoices: dataObj.invoices.length,
      data: JSON.stringify(dataObj),
    };

    list.push(snap);

    // Limit "bill" snapshots to last 5 so they don't crowd daily ones
    const billOnes = list.filter((x) => x.kind === 'bill');
    if (billOnes.length > 5) {
      const dropIds = new Set(billOnes.slice(0, billOnes.length - 5).map((x) => x.id));
      const filtered = list.filter((x) => !dropIds.has(x.id));
      list.length = 0;
      list.push(...filtered);
    }

    while (list.length > MAX_SNAPSHOTS) {
      list.shift();
    }

    writeSnapshots(list);
    return snap;
  } catch (e) {
    console.error('Failed to create snapshot', e);
    return null;
  }
}

export function restoreSnapshot(snapshotId: string): AppStoreData | null {
  const list = readSnapshots();
  const snap = list.find((x) => x.id === snapshotId);
  if (!snap) return null;

  try {
    const current = loadStore();
    createSnapshot(`Before restoring ${snap.label}`, 'pre-restore', current);

    const parsed: AppStoreData = JSON.parse(snap.data);
    saveStore(parsed);
    return parsed;
  } catch (e) {
    console.error('Failed to restore snapshot', e);
    return null;
  }
}

export function exportBackupJson(): string {
  const current = loadStore();
  try {
    localStorage.setItem(
      LAST_EXPORT_KEY,
      JSON.stringify({ ts: new Date().toISOString(), invoices: current.invoices.length })
    );
  } catch (e) {}
  return JSON.stringify(current, null, 2);
}

export function importBackupJson(jsonString: string): { success: boolean; error?: string } {
  try {
    const parsed = JSON.parse(jsonString);
    if (!parsed || typeof parsed !== 'object') {
      return { success: false, error: 'File content is not valid JSON.' };
    }
    if (!Array.isArray(parsed.products) || !Array.isArray(parsed.invoices)) {
      return { success: false, error: 'Missing required products or invoices data structure.' };
    }

    // Save a pre-restore backup first
    createSnapshot('Before importing backup file', 'pre-restore');

    const imported: AppStoreData = {
      version: parsed.version || '2.0',
      products: parsed.products,
      invoices: parsed.invoices,
      heldBills: Array.isArray(parsed.heldBills) ? parsed.heldBills : [],
      customers: Array.isArray(parsed.customers) ? parsed.customers : [],
      customerPayments: Array.isArray(parsed.customerPayments) ? parsed.customerPayments : [],
      suppliers: Array.isArray(parsed.suppliers) ? parsed.suppliers : [],
      purchases: Array.isArray(parsed.purchases) ? parsed.purchases : [],
      expenses: Array.isArray(parsed.expenses) ? parsed.expenses : [],
      stockAdjustments: Array.isArray(parsed.stockAdjustments) ? parsed.stockAdjustments : [],
      shopInfo: {
        ...DEFAULT_SHOP_INFO,
        ...(parsed.shopInfo || {}),
        logo: (parsed.shopInfo && parsed.shopInfo.logo) || SHOP_LOGO_DATA_URI,
      },
    };

    saveStore(imported);
    return { success: true };
  } catch (e: any) {
    return { success: false, error: e?.message || 'Invalid JSON file format' };
  }
}

export function resetToSeedData(): AppStoreData {
  createSnapshot('Before Factory Reset', 'pre-restore');
  const fresh: AppStoreData = {
    version: '2.0',
    products: SEED_PRODUCTS,
    invoices: SEED_INVOICES,
    heldBills: [],
    customers: SEED_CUSTOMERS,
    customerPayments: [],
    suppliers: SEED_SUPPLIERS,
    purchases: [],
    expenses: SEED_EXPENSES,
    stockAdjustments: [],
    shopInfo: DEFAULT_SHOP_INFO,
  };
  saveStore(fresh);
  return fresh;
}

export function downloadCsv(filename: string, headers: string[], rows: (string | number)[][]) {
  const escapeCsv = (val: string | number) => {
    const str = String(val ?? '');
    if (str.includes(',') || str.includes('"') || str.includes('\n')) {
      return `"${str.replace(/"/g, '""')}"`;
    }
    return str;
  };

  const csvContent =
    '\uFEFF' +
    [headers.map(escapeCsv).join(','), ...rows.map((row) => row.map(escapeCsv).join(','))].join('\n');

  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.setAttribute('href', url);
  link.setAttribute('download', filename);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}
